'use strict';
Object.assign(Meta,{
  showHero(key,form){
    this.selectedHero=key;const h=this.model.hero(key);if(!h)return;
    const o=this.model.state.owned[key],max=o?20+o.awake*20:20,awakened=form?form==='awakened':h.awake>0;this.previewAwake=awakened;
    const levels=o?Math.min(5,max-o.level):0;
    openModal('hero',`<div class="hero-detail"><div class="detail-art clean-portrait" style="--hero-tint:${h.color}"><img src="${this.image({...h,awake:awakened?1:0})}" alt="${h.name}${awakened?'突破形态':'基础形态'}"><div><small>${h.element} · ${h.role} · ${h.type}</small><h2>${h.name}</h2><span class="gold-stars">${this.stars(h.rarity)}</span></div></div><div class="detail-body"><div class="form-switch"><button data-meta="hero-form" data-form="base" class="${!awakened?'active':''}">基础立绘</button><button data-meta="hero-form" data-form="awakened" class="${awakened?'active':''}">突破立绘</button><button data-meta="form-compare">形态对照</button></div><p class="form-caption">${awakened?h.formTitle+' · '+(o?.awake?'已解锁':'首次突破后解锁 · 当前为预览'):'初始契约 · '+h.combatRole}</p><p class="hero-lore">${h.lore}</p><div class="hero-stats"><div><small>等级</small><b>${o?o.level:1}<em> / ${max}</em></b></div><div><small>攻击</small><b>${h.attack}</b></div><div><small>生命</small><b>${h.hp}</b></div><div><small>幸运</small><b>${o?.luck||1}</b></div></div><div class="skill-description"><span>友情援护 · ${h.combatRole}</span><h3>${h.skill}</h3><p>${h.description}</p></div><div class="skill-description personal-ultimate"><span>专属秘术 · 能量 100 后弹射发动</span><h3>${h.ultimate}</h3><p>${h.ultimateDescription}</p><small>当前成长倍率 ×${h.supportScale.toFixed(2)} · ${h.type==='贯通'?'贯通型可以穿过敌人。':'反射型利用反弹制造连续伤害。'}</small></div><button class="silver-button trial-button" data-meta="practice-hero">试用这位角色 · 不耗体力</button><p class="range-note">触碰同伴后，援护从同伴所在位置发动。圆域看距离，激光看射线；方向型援护跟随触发者的前进方向。演练可查看援护范围。</p>${o?`<div class="growth-title"><b>灵魂强化</b><small>金币 ∞ · 残响 ∞ · 古印 ∞</small></div><div class="growth-buttons"><button class="silver-button" data-meta="train" data-count="1" ${!levels?'disabled':''}>升级 1 次<small>免费强化</small></button><button class="embossed-button" data-meta="train" data-count="5" ${!levels?'disabled':''}>强化 ${levels||5} 级<small>免费强化</small></button></div><button class="awaken-button" data-meta="awaken" ${o.level<max||o.awake>=4?'disabled':''}><span>✧ 突破觉醒 ${o.awake} / 4</span><small>${o.awake>=4?'已完全觉醒':`Lv.${max} 可免费突破 · 上限 ${max+20}${o.awake===0?' · 解锁新立绘':''}`}</small></button><div class="shards-row"><span>魂片 ∞ · 幸运 ${o.luck}/99</span><button class="text-button" data-meta="luck" ${o.luck>=99?'disabled':''}>${o.luck>=99?'幸运已满':'强化幸运 +'+Math.min(5,99-o.luck)}</button></div><button class="text-button detail-team-button" data-meta="team">${this.icon('team')} 编入小队</button>`:`<div class="unowned-note">尚未签订契约 · 可在群星召唤中获得</div><button class="embossed-button" data-meta="go-summon">前往召唤</button>`}</div></div>`);
  },
  compareForms(){const h=this.model.hero(this.selectedHero);openModal('forms',`<div class="modal-kicker">CHARACTER EVOLUTION</div><h2>${h.name} · 形态对照</h2><div class="form-comparison"><figure><img src="${this.image({...h,awake:0})}" alt="基础立绘"><figcaption>基础契约</figcaption></figure><figure><img src="${this.image({...h,awake:1})}" alt="突破立绘"><figcaption>${h.formTitle}</figcaption></figure></div><p>首次突破解锁新立绘，大厅、卡面、战场弹珠和秘术特写会同步切换。后续突破继续提高等级上限与属性。</p><button class="primary-button" data-meta="hero" data-key="${h.key}">返回角色</button>`);},
  bossInfo(chapter){const key=AbyssProgress.CHAPTERS[chapter]?.bossKey,b=AbyssKit.BOSSES[key];if(!b)return;openModal('boss-info',`<div class="modal-kicker">BOSS FIELD GUIDE</div><h2>${b.name} · 作战情报</h2><p>按顺序循环使用三种招式。倒计时结束后结算伤害；带纹理的区域代表危险范围。</p><div class="boss-moves">${b.moves.map((m,i)=>`<div><b>0${i+1} · ${m.name}</b><p>${m.hint}</p></div>`).join('')}</div><p class="phase-note">生命降至 50%：${b.phase}，伤害提高并加快当前招式。</p><div class="modal-actions"><button class="secondary-button" data-action="resume">返回</button><button class="primary-button" data-meta="practice-boss" data-chapter="${chapter}">招式演练 · 免费</button></div>`);},
  practiceSpot(){
    const hero=game.heroes[0],candidates=[{x:250,y:315},{x:250,y:285},{x:250,y:345},{x:195,y:315},{x:305,y:315},{x:250,y:375}];
    const free=p=>game.pillars.every(o=>Math.hypot(p.x-o.x,p.y-o.y)>hero.r+o.r+8)&&game.enemies.every(o=>o.hp<=0||Math.hypot(p.x-o.x,p.y-o.y)>hero.r+o.r+8);
    const spot=candidates.find(free);if(spot)return spot;
    const center=candidates[0];game.pillars=game.pillars.filter(o=>Math.hypot(center.x-o.x,center.y-o.y)>hero.r+o.r+8);return center;
  },
  resetPracticeActors(active){
    for(const h of game.heroes){h.vx=0;h.vy=0;}
    Object.assign(game.heroes[0],this.practicePoint);if((game.heroes[0].key||game.heroes[0].art)==='sable'){Object.assign(game.heroes[2],{x:170,y:350});Object.assign(game.heroes[3],{x:330,y:350});}game.active=active;game.spatial=[];game.shotKit=null;game.armed=false;game.powered=false;aim=null;
  },
  openPractice(key,chapter=0,awake,bossTrial=false){
    const h=AbyssProgress.CATALOG.find(h=>h.key===key);if(!h)return;
    const previewAwake=awake===undefined?this.model.state.owned[key]?.awake||0:awake?1:0,party=[h,...[key==='iris'?'nyra':'iris','lucia','silas','evelyn'].filter(k=>k!==key).slice(0,3).map(k=>AbyssProgress.CATALOG.find(h=>h.key===k))].map((v,i)=>AbyssProgress.stats(v,{level:20,awake:i===0?previewAwake:0,luck:1}));
    const quest=AbyssProgress.QUESTS.filter(q=>q.chapter===chapter).at(-1),stage=AbyssProgress.waves(quest).at(-1);stage.name=bossTrial?'首领演练 · '+stage.title:'技能演练 · '+h.name;stage.pillars=[];stage.enemies=stage.enemies.map(e=>({...e,hp:50000,damage:300,counter:e.bossKind?1:3}));this.trainingChapter=bossTrial?chapter:null;this.training=true;this.enterBattle({tactical:true,stages:[stage],party,maxHp:40000});this.practicePoint=this.practiceSpot();this.resetPracticeActors(0);for(const boss of game.enemies.filter(e=>e.bossKind))game.planBoss(boss);game.energy=100;uiDirty=true;updateUI();$('trainingControls').querySelector('span').textContent=bossTrial?'切换招式可查看预警，首领试放可立即结算 · 不耗体力':'援护试射：让同伴行动，触发试用角色的援护 · 不耗体力';
    if(bossTrial) $('aimHelp').style.display='none';
    else message('援护试射 · 同伴行动，触发试用角色',2200);
  }
});

Meta.init();
